<?php $fs=static fn(string $s):string=>ucfirst(str_replace('_',' ',$s)); ?>
<header class="panel-page-heading"><div><span>Administracao</span><h1>Reservas</h1><p>Gestao do ciclo de vida das reservas.</p></div></header>
<section class="panel-card"><form method="get" action="<?= url('/admin/reservas') ?>"><label>Status <input name="status" value="<?= e($status) ?>"></label><button class="btn btn-primary">Filtrar</button></form></section>
<section class="panel-card"><div class="responsive-table"><table class="panel-table"><thead><tr><th>Reserva</th><th>Imovel</th><th>Cliente</th><th>Proprietario</th><th>Status</th><th>Pagamento</th><th></th></tr></thead><tbody><?php foreach($reservas as $r): ?><tr><td>#<?= (int)$r['id'] ?></td><td><?= e($r['chacara_nome']) ?></td><td><?= e($r['cliente_nome']) ?></td><td><?= e($r['proprietario_nome']) ?></td><td><span class="status-pill"><?= e($fs($r['status_reserva'])) ?></span></td><td><span class="status-pill status-payment"><?= e($fs($r['status_pagamento'])) ?></span></td><td><a class="btn btn-outline" href="<?= url('/admin/reservas/'.(int)$r['id']) ?>">Detalhes</a></td></tr><?php endforeach; ?></tbody></table></div></section>
